            int i=0;foreach(var f in motel.GetComponentsInChildren<MeshFilter>()){var r=f.GetComponent<MeshRenderer>();if(r==null||!Driveways.Any(c=>c.Overlaps(Footprint(r.bounds))))continue;bool ground=GroundSurfaceStyle.SurfaceFor(r.name)==5||r.name=="Low sidewalk curb"||r.name=="Retained public sidewalk";if(ground)AsterAccessMeshClipper.ClipLowGround(f,Driveways,Folder+"/ClippedPublicPaving"+(i++)+".asset");}
            foreach(var c in motel.GetComponentsInChildren<BoxCollider>()){var b=c.bounds;if(!c.enabled||b.max.y>.25f||!Driveways.Any(d=>d.Overlaps(Footprint(b))))continue;if(GroundSurfaceStyle.SurfaceFor(c.name)!=5&&c.name!="Low sidewalk curb"&&c.name!="Retained public sidewalk")continue;c.enabled=false;foreach(var r in StreetPavingLayout.ClearRoads(Footprint(b),Driveways)){var n=new GameObject("Retained street paving collision",typeof(BoxCollider));n.transform.SetParent(target,false);var a=n.GetComponent<BoxCollider>();a.center=new Vector3(r.center.x,b.center.y,r.center.y);a.size=new Vector3(r.width,b.size.y,r.height);}}
        }
        private static Rect Footprint(Bounds b)=>Rect.MinMaxRect(b.min.x,b.min.z,b.max.x,b.max.z);
        private static void RoofPlant(Transform r,Vector3 p){Pipe(r,"Small garden trunk",p,p+Vector3.up*2.4f,.2f,wood);foreach(int s in new[]{-1,1})Box(r,"Garden olive canopy",p+new Vector3(s*.6f,2.7f,0),new Vector3(2.1f,1.6f,2.2f),leaf,false,PrimitiveType.Sphere);}
        private static void Pergola(Transform r,Vector3 p,float w,float d){var g=Group(r,"Roof garden pergola",p);foreach(int s in new[]{-1,1})foreach(int e in new[]{-1,1})Box(g,"Pergola support",new Vector3(s*w/2,1.5f,e*d/2),new Vector3(.14f,3,.14f),bronze,false);for(float x=-w/2;x<=w/2;x+=.55f)Box(g,"Pergola walnut blade",new Vector3(x,3.05f,0),new Vector3(.12f,.18f,d+.5f),wood,false);}
        private static void Planter(Transform r,Vector3 p,float w,float d){Box(r,"Stone planter",p+Vector3.up*.26f,new Vector3(w,.4f,d),stone,true);Box(r,"Planter soil",p+Vector3.up*.47f,new Vector3(w-.16f,.03f,d-.16f),soil,false);for(float x=-w*.4f;x<=w*.4f;x+=Mathf.Max(.55f,w/10))Box(r,"Planter shrub",p+new Vector3(x,.66f,0),new Vector3(Mathf.Max(.7f,w/9),.6f,d*.7f),leaf,false,PrimitiveType.Sphere);}
