        private static void Table(Transform r,Vector3 p,bool dining){float h=dining?1.1f:.6f;Box(r,"Table pedestal",p+Vector3.up*h*.5f,new Vector3(.18f,h,.18f),ink,true);Box(r,"Round stone table",p+Vector3.up*h,new Vector3(dining?2.4f:2,.07f,dining?2.4f:2),stone,false,PrimitiveType.Cylinder);Box(r,"Table herb pot",p+new Vector3(0,h+.15f,0),new Vector3(.24f,.12f,.24f),bronze,false,PrimitiveType.Cylinder);Box(r,"Table herb",p+new Vector3(0,h+.4f,0),new Vector3(.3f,.4f,.3f),leaf,false,PrimitiveType.Sphere);if(dining)foreach(int s in new[]{-1,1}){Box(r,"Table ceramic plate",p+new Vector3(s*.65f,h+.09f,0),new Vector3(.45f,.02f,.45f),ivory,false,PrimitiveType.Cylinder);Box(r,"Dining glass",p+new Vector3(s*.65f,h+.22f,.4f),new Vector3(.12f,.13f,.12f),glass,false,PrimitiveType.Cylinder);}}
        private static void Chair(Transform r,Vector3 p,float yaw){var g=Group(r,"Dining chair",p,yaw);Box(g,"Chair seat",new Vector3(0,.62f,0),new Vector3(.85f,.15f,.8f),linen,true);Box(g,"Chair back",new Vector3(0,1,.36f),new Vector3(.85f,.75f,.12f),wood,false);foreach(int s in new[]{-1,1})foreach(int e in new[]{-1,1})Box(g,"Chair leg",new Vector3(s*.3f,.34f,e*.3f),new Vector3(.055f,.55f,.055f),ink,false);}
