        private static void Lantern(Transform r,Vector3 p){Box(r,"Street lighting mast",p+Vector3.up*2,new Vector3(.12f,3.8f,.12f),ink,true);var b=Box(r,"District light diffuser",p+Vector3.up*4,new Vector3(.65f,.12f,.65f),warm,false);lamps.Add(b.GetComponent<Renderer>());}
        private static void Floor(Transform r,string name,Rect a,float y,Material m){var go=MeshPart(r,name+" surface",new[]{new Vector3(a.xMin,y,a.yMin),new Vector3(a.xMin,y,a.yMax),new Vector3(a.xMax,y,a.yMax),new Vector3(a.xMax,y,a.yMin)},new[]{0,1,2,0,2,3},m);var c=go.AddComponent<BoxCollider>();c.center=new Vector3(a.center.x,y-.08f,a.center.y);c.size=new Vector3(a.width,.16f,a.height);}
        private static GameObject MeshPart(Transform r,string name,Vector3[] v,int[] t,Material m){var mesh=new Mesh{name=name,vertices=v,triangles=t,uv=v.Select(p=>new Vector2(p.x*.3f,p.z*.3f)).ToArray()};mesh.RecalculateNormals();mesh.RecalculateBounds();var go=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(r,false);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<MeshRenderer>().sharedMaterial=m;return go;}
        private static Transform Group(Transform r,string name,Vector3 p,float yaw=0){var g=new GameObject(name).transform;g.SetParent(r,false);g.localPosition=p;g.localRotation=Quaternion.Euler(0,yaw,0);return g;}
        private static void Pipe(Transform r,string name,Vector3 a,Vector3 b,float w,Material m,bool solid=false){var g=Box(r,name,(a+b)*.5f,new Vector3(w,(b-a).magnitude,w),m,solid);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
        private static void Paint(Transform r,Vector3 p,Vector3 size,Material m)=>Box(r,"Flush court paint",p,size,m,false);
        private static GameObject Box(Transform r,string name,Vector3 p,Vector3 size,Material m,bool solid,PrimitiveType shape=PrimitiveType.Cube){var go=GameObject.CreatePrimitive(shape);go.name=name;go.transform.SetParent(r,false);go.transform.localPosition=p;go.transform.localScale=size;go.GetComponent<MeshRenderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(go.GetComponent<Collider>());if(solid)go.AddComponent<BoxCollider>();return go;}
        private static void Sign(Transform r,string title,Vector3 p,float size,float width,Color c,float yaw=0){var t=new GameObject(title).AddComponent<TextMeshPro>();t.transform.SetParent(r,false);t.transform.localPosition=p;t.transform.localRotation=Quaternion.Euler(0,yaw,0);t.font=TMP_Settings.GetFontAsset();t.text=title;t.fontSize=size*10;t.alignment=TextAlignmentOptions.Center;t.color=c;t.rectTransform.sizeDelta=new Vector2(width,size*3.5f);t.raycastTarget=false;}
        private static Material Mat(string name,Color c,float smooth,string texture=null){string path=Folder+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=c;m.SetFloat("_Smoothness",smooth);m.enableInstancing=true;if(texture!=null){m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/_Game/Art/Surfaces/"+texture+"_Albedo.png");m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/_Game/Art/Surfaces/"+texture+"_Normal.png"));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.15f);}EditorUtility.SetDirty(m);return m;}
        private static Transform Top(Transform t,Transform root){while(t.parent!=root&&t.parent!=null)t=t.parent;return t;}
        private static void Merge(Transform root,MeshFilter[] parts,Material m,string path)
        {
            var mesh=new Mesh{name="Grand Boulevard "+m.name,indexFormat=IndexFormat.UInt32};mesh.CombineMeshes(parts.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray(),true,true);mesh.RecalculateBounds();var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else{saved.Clear();EditorUtility.CopySerialized(mesh,saved);saved.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(mesh);}var go=new GameObject(saved.name,typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(root,false);go.GetComponent<MeshFilter>().sharedMesh=saved;go.GetComponent<MeshRenderer>().sharedMaterial=m;foreach(var f in parts){UnityEngine.Object.DestroyImmediate(f.GetComponent<MeshRenderer>());UnityEngine.Object.DestroyImmediate(f);}
        }
        private static void Combine(Transform root)
        {
            foreach(var door in root.GetComponentsInChildren<DistrictSlidingDoor>())foreach(Transform panel in door.transform)foreach(var g in panel.GetComponentsInChildren<MeshFilter>().GroupBy(f=>f.GetComponent<MeshRenderer>().sharedMaterial).ToArray())Merge(panel,g.ToArray(),g.Key,Folder+"/DoorMesh"+(meshIndex++)+".asset");
            int i=0;var filters=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<TMP_Text>()==null&&f.GetComponentInParent<DistrictSlidingDoor>()==null&&!lamps.Contains(f.GetComponent<Renderer>())).ToArray();foreach(var g in filters.GroupBy(f=>new{Mat=f.GetComponent<MeshRenderer>().sharedMaterial,Bucket=f.GetComponent<MeshRenderer>().sharedMaterial==glass?Top(f.transform,root).name:""}))Merge(root,g.ToArray(),g.Key.Mat,Folder+"/District"+(i++)+".asset");
        }
        private static void RegisterLights(MotelGameRoot m){var l=m.GetComponentInChildren<WorldNightLighting>();if(l==null)return;var so=new SerializedObject(l);var a=so.FindProperty("fixtures");var b=so.FindProperty("glowingSurfaces");int ai=a.arraySize,bi=b.arraySize;a.arraySize+=lamps.Count;b.arraySize+=lamps.Count;for(int i=0;i<lamps.Count;i++){a.GetArrayElementAtIndex(ai+i).objectReferenceValue=lamps[i].transform;b.GetArrayElementAtIndex(bi+i).objectReferenceValue=lamps[i];}so.ApplyModifiedPropertiesWithoutUndo();}
    }
